use axum::{extract::{Path, State}, http::StatusCode};
use serde_json::{Value, json};
use crate::{domain::{models::{entity_details::{MemberProfile, MemberDetails, FunderDetails}, funder::FunderId, parliament_member::MemberId}, services::{entity_details::{EntityDetailsError, EntityDetailsService}, entity_search::EntitySearchService}}, inbound::http::{error::ApiError, state::AppState, success::ApiSuccess}};

impl From<EntityDetailsError> for ApiError {
    fn from(error: EntityDetailsError) -> Self {
        match error { EntityDetailsError::NotFound => Self::NotFound, EntityDetailsError::Unexpected(_) => Self::InternalServerError }
    }
}

fn member_response(member: &MemberProfile) -> Value {
    json!({ "id": member.id.value().to_string(), "name": member.name, "party_id": member.party_id, "party_name": member.party_name, "constituency": member.constituency, "is_current_commons": member.is_current_commons })
}

fn member_details_response(details: &MemberDetails) -> Value {
    let declarations: Vec<_> = details.declarations.iter().map(|declaration| {
        let entries: Vec<_> = declaration.entries.iter().map(|entry| json!({
            "funder": entry.funder.as_ref().map(|funder| json!({"id": funder.id.value().to_string(), "name": funder.name})),
            "amount": entry.amount.as_ref().map(ToString::to_string), "currency": entry.currency, "payment_type": entry.payment_type
        })).collect();
        json!({"source_id": declaration.source_id, "category_name": declaration.category_name, "registered_at": declaration.registered_at, "entries": entries})
    }).collect();
    json!({ "member": member_response(&details.member), "declarations": declarations, "declaration_count": details.declaration_count, "declaration_limit": details.declaration_limit })
}

fn funder_details_response(details: &FunderDetails) -> Value {
    let currencies: Vec<_> = details.currencies.iter().map(|group| {
        let parties: Vec<_> = group.parties.iter().map(|party| json!({"party_id": party.party_id, "party_name": party.party_name, "amount": party.amount.as_ref().map(ToString::to_string), "entry_count": party.entry_count, "unknown_amount_count": party.unknown_amount_count})).collect();
        let recipients: Vec<_> = group.top_recipients.iter().map(|recipient| json!({"member": member_response(&recipient.member), "amount": recipient.known_total.as_ref().map(ToString::to_string), "entry_count": recipient.entry_count, "unknown_amount_count": recipient.unknown_amount_count})).collect();
        json!({"currency": group.currency, "parties": parties, "top_recipients": recipients})
    }).collect();
    json!({ "funder": {"id": details.profile.funder.id().value().to_string(), "name": details.profile.funder.name(), "funder_kind": details.profile.funder.kind(), "company_number": details.profile.company_number}, "currencies": currencies, "entry_count": details.entry_count, "unknown_currency_count": details.unknown_currency_count, "recipient_limit": details.recipient_limit })
}

pub async fn member_details<E: EntitySearchService, D: EntityDetailsService>(State(state): State<AppState<E,D>>, Path(id): Path<String>) -> Result<ApiSuccess<Value>, ApiError> {
    let id = id.parse::<MemberId>().map_err(ApiError::UnprocessibleEntity)?;
    let details = state.entity_details_service.member(id).await?;
    Ok(ApiSuccess::new(StatusCode::OK, member_details_response(&details)))
}

pub async fn funder_details<E: EntitySearchService, D: EntityDetailsService>(State(state): State<AppState<E,D>>, Path(id): Path<String>) -> Result<ApiSuccess<Value>, ApiError> {
