use bigdecimal::BigDecimal;
use sqlx::PgPool;
use crate::{domain::{models::{funder::FunderId, parliament_member::MemberId}, repositories::entity_details::EntityDetailsRepo, services::entity_details::{EntityDetailsService, Service, EntityDetailsError}}, outbound::postgres::ExposedDatabase};

const FUNDER: &str = "10000000-0000-0000-0000-000000000001";

#[sqlx::test(migrations = "../db/migrations", fixtures("fixtures.sql"))]
async fn recent_window_preserves_occurrences_and_empty_declarations(pool: PgPool) {
    let db = ExposedDatabase::from(pool);
    let service = Service::new(db);
    let details = service.member("1".parse().unwrap()).await.unwrap();
    assert_eq!(details.declaration_count, 23);
    assert_eq!(details.declaration_limit, 20);
    assert_eq!(details.declarations.iter().map(|declaration| declaration.source_id).collect::<Vec<_>>(), (101..=120).rev().collect::<Vec<_>>());
    assert_eq!(details.declarations[0].entries.len(), 7);
    let duplicate = details.declarations[0].entries.iter().filter(|entry| entry.amount == Some("9007199254740993.123456789".parse::<BigDecimal>().unwrap())).count();
    assert_eq!(duplicate, 2);
    assert!(details.declarations[0].entries.iter().any(|entry| entry.funder.is_none() && entry.amount.is_none() && entry.currency.is_none()));
    assert!(details.declarations[1..].iter().all(|declaration| declaration.entries.is_empty()));
    let details = service.member("2".parse().unwrap()).await.unwrap();
    assert_eq!(details.declarations.iter().map(|declaration| declaration.source_id).collect::<Vec<_>>(), vec![202, 201, 200]);
    assert!(details.declarations[2].registered_at.is_none());
    assert!(details.declarations[0].registered_at.is_some());
    assert!(service.member("3".parse().unwrap()).await.unwrap().declarations.is_empty());
    assert!(matches!(service.member("999".parse().unwrap()).await, Err(EntityDetailsError::NotFound)));
}

#[sqlx::test(migrations = "../db/migrations", fixtures("fixtures.sql"))]
async fn exact_summaries_exclude_unknown_currencies_and_keep_local_coverage(pool: PgPool) {
    let db = ExposedDatabase::from(pool);
    let raw = db.funder_funding(FUNDER.parse().unwrap()).await.unwrap().unwrap();
    assert!(raw.allocations.iter().filter(|allocation| allocation.currency.is_none()).all(|allocation| allocation.known_total.is_none()));
    let details = Service::new(db).funder(FUNDER.parse().unwrap()).await.unwrap();
    assert_eq!(details.profile.company_number.as_deref(), Some("00123456"));
    assert_eq!(details.entry_count, 22);
    assert_eq!(details.unknown_currency_count, 3);
    assert_eq!(details.currencies.iter().map(|group| group.currency.as_str()).collect::<Vec<_>>(), vec!["EUR", "GBP", "USD"]);
    let eur = &details.currencies[0];
    assert!(eur.parties[0].amount.is_none());
    assert_eq!(eur.parties[0].unknown_amount_count, 1);
    assert!(eur.top_recipients[0].known_total.is_none());
    let gbp = &details.currencies[1];
    assert_eq!(gbp.parties[0].amount, Some("18014398509481998.246913578".parse::<BigDecimal>().unwrap()));
    assert_eq!(gbp.parties[0].entry_count, 15);
    assert_eq!(gbp.parties[0].unknown_amount_count, 1);
    assert_eq!(gbp.parties[1].amount, Some("-5".parse::<BigDecimal>().unwrap()));
    assert_eq!(gbp.parties[1].unknown_amount_count, 0);
    assert_eq!(gbp.top_recipients.len(), 10);
    assert_eq!(gbp.top_recipients[0].known_total, Some("18014398509481986.246913578".parse::<BigDecimal>().unwrap()));
    assert_eq!(gbp.top_recipients[0].unknown_amount_count, 1);
    assert_eq!(gbp.top_recipients.iter().map(|allocation| allocation.member.id.value()).collect::<Vec<_>>(), vec![1,4,5,6,7,8,9,10,11,12]);
    assert_eq!(details.currencies[2].top_recipients[0].member.id.value(), 2);
    assert_eq!(details.currencies[2].parties[0].amount, Some("500".parse::<BigDecimal>().unwrap()));
}

