#[sqlx::test(migrations = "../db/migrations", fixtures("details"))]
async fn http_handlers_expose_typed_identities_exact_values_and_statuses(pool: PgPool) {
    use std::sync::Arc;
    use crate::{domain::services::entity_search, inbound::http::{routes::routes, state::AppState}};
    let db = ExposedDatabase::from(pool);
    let state = AppState { entity_search_service: Arc::new(entity_search::Service::new(db.clone(), db.clone())), entity_details_service: Arc::new(Service::new(db.clone())) };
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let origin = format!("http://{}", listener.local_addr().unwrap());
    let server = tokio::spawn(async move { axum::serve(listener, routes().with_state(state)).await.unwrap(); });
    let client = reqwest::Client::new();
    let response = client.get(format!("{origin}/members/1")).send().await.unwrap();
    assert_eq!(response.status(), reqwest::StatusCode::OK);
    let body: serde_json::Value = response.json().await.unwrap();
    assert_eq!(body["member"]["id"], "1");
    assert_eq!(body["declarations"].as_array().unwrap().len(), 20);
    let entries = body["declarations"][0]["entries"].as_array().unwrap();
    assert_eq!(entries.iter().filter(|entry| entry["amount"] == "9007199254740993.123456789").count(), 2);
    assert!(entries.iter().any(|entry| entry["funder"].is_null()));
    let response = client.get(format!("{origin}/funders/{FUNDER}")).send().await.unwrap();
    assert_eq!(response.status(), reqwest::StatusCode::OK);
    let body: serde_json::Value = response.json().await.unwrap();
    assert_eq!(body["funder"]["id"], FUNDER);
    assert_eq!(body["currencies"][0]["parties"][0]["amount"], serde_json::Value::Null);
    assert_eq!(body["currencies"][1]["parties"][0]["amount"], "18014398509481998.246913578");
    let response = client.get(format!("{origin}/search?term=Exact%20Funder&max_entries=10&strictness=1")).send().await.unwrap();
    let body: serde_json::Value = response.json().await.unwrap();
    assert_eq!(body["entities"][0]["id"], FUNDER);
    for path in ["members/0", "members/2147483648", "members/nope", "funders/not-a-uuid"] {
        assert_eq!(client.get(format!("{origin}/{path}")).send().await.unwrap().status(), reqwest::StatusCode::UNPROCESSABLE_ENTITY);
    }
    for path in ["members/999", "funders/10000000-0000-0000-0000-000000000003"] {
        assert_eq!(client.get(format!("{origin}/{path}")).send().await.unwrap().status(), reqwest::StatusCode::NOT_FOUND);
    }
    db.pool().close().await;
    let response = client.get(format!("{origin}/members/1")).send().await.unwrap();
    assert_eq!(response.status(), reqwest::StatusCode::INTERNAL_SERVER_ERROR);
    assert_eq!(response.text().await.unwrap(), "internal server error");
    server.abort();
}
